# ideogram — generated by tools/gen_model_py.py from the yaml
# cascade (2026-09-02 flip), then hand-edited since. The
# class IS the unit: family head → variants → quant cells;
# merged_defaults() walks the cascade. Parity pinned by
# tests/walls/suites/test_python_models.py + the http goldens.
#
# SSOT law: this file REPLACES model.yaml + variants/. A
# model.yaml reappearing next to it is a LOUD refusal.
#
# BOARDED to the ideogram4 card (2026-09-05 — the unboarded
# "data family" era retired by operator order: every offered
# model runs). Dual-guided family: conditional + unconditional
# unets through DualModelGuider, flux2 VAE, the Ideogram4
# scheduler (mu/std) — a graph shape the shared image-gen
# renderer does not speak, so the family boards its OWN card
# arm (action_cards/image/ideogram4) while riding the SAME
# editor form (form_generate).


from melite_models import  KnobRow,Model, Variant, Cell, LoraRow, Studio, LaneInputs, Genre, ClipType


class Ideogram(Model):
    id = 'ideogram'
    genre = Genre.IMAGE
    label = 'Ideogram'
    description = 'Typography-aware text-to-image with clean, legible text rendering.'
    studio = Studio(tenant='image/canvas-ideogram')
    form = 'form_generate'
    engine = 'comfyui'
    card = 'ideogram4'           # the owning card (cross-validation hook)
    # the Comfy-Org official template's Default preset: 20 steps,
    # mu 0.5, std 1.75, guider cfg 7 (the negative is the zeroed
    # conditioning — ConditioningZeroOut — not a text channel)
    defaults = dict(
            mu=0.5,
            std=1.75,
            width=1024,
            height=1024,
            steps=20,
            sampler='euler',
            cfg=7.0,
        )
    # the cascade as frozen rows (PYTHON SHAPE LAW rung 1). ONE
    # variant: nvfp4 mixed — the provisioned checkpoint pair on the
    # mount. The fp8 conditional is not provisioned; a variant
    # without weights is an offer that cannot run.
    variants = (
        Variant(id='nf4', label='NF4', hint='nvfp4 mixed-precision — DEFAULT', route='ideogram', order=0),
    )

    # loader stack — the weight facts the card renderer reads; the
    # dual-guided shape states BOTH unet basenames ONCE (rung 6:
    # never restated beside the files)
    lane_inputs = LaneInputs(
        unet='ideogram4_nvfp4_mixed.safetensors',
        unet_unconditional='ideogram4_unconditional_nvfp4_mixed.safetensors',
        text_encoder='qwen3vl_8b_nvfp4.safetensors',
        clip_type=ClipType.IDEOGRAM4,
        vae='flux2-vae.safetensors',
        latent_node='EmptyFlux2LatentImage',
    )

    # the ideogram4 card surface (row 3, 2026-09-06 — eighth card in
    # the KnobRow migration). Nine rows, card vocabulary throughout
    # (no renames needed). width/height FAN OUT in the renderer
    # (latent canvas + scheduler sigmas shape) — the row model is
    # 1:1, so rows target the canvas (the knob's meaning; the
    # image-gen width precedent) and name the scheduler mirror here.
    card_knobs = (
        KnobRow(card='prompt', inject='CLIPTextEncode.0.text', kind='s'),
        KnobRow(card='width', inject='EmptyFlux2LatentImage.0.width', kind='n'),
        KnobRow(card='height', inject='EmptyFlux2LatentImage.0.height', kind='n'),
        KnobRow(card='steps', inject='Ideogram4Scheduler.0.steps', kind='n'),
        KnobRow(card='cfg', inject='DualModelGuider.0.cfg', kind='n'),
        KnobRow(card='mu', inject='Ideogram4Scheduler.0.mu', kind='n'),
        KnobRow(card='std', inject='Ideogram4Scheduler.0.std', kind='n'),
        KnobRow(card='sampler', inject='KSamplerSelect.0.sampler_name', kind='s'),
        KnobRow(card='seed', inject='RandomNoise.0.noise_seed', kind='n'),
    )
